    private static final String LOG_PATH = "target/api-suite.log";

    private static final DateTimeFormatter TS = DateTimeFormatter.ofPattern("HH:mm:ss.SSS");

    private static PrintWriter file; // guarded by TestLog.class
    private static boolean fileFailed; // do not retry a broken path on every line

    private TestLog() {}

    public static void info(String message) {
        write("INFO", message);
    }

    public static void warn(String message) {
        write("WARN", message);
    }

    public static void error(String message) {
        write("ERROR", message);
    }

    /**
     * A titled multi-line block — a request or response body.
     *
     * <p>Rendered as a code block in the report and indented in the console and
     * log file, so a pretty-printed body stays readable instead of collapsing
     * into one unreadable line.
     */
    public static void block(String title, String body) {
        if (body == null || body.isBlank()) return;
        write("INFO", title);
        body = redact(body);
        String indented = body.strip().replace("\n", "\n        ");
        console("        " + indented);
        toFile("        " + indented);
        ReportLog.code(body.strip());
    }

    /**
     * Blanks anything that looks like a credential.
     *
     * <p>Lives here, not in the recorder, because this is the one place every
     * logged body passes through — console, log file and report alike. Kept
     * deliberately blunt: a false positive costs a line of detail, a false
     * negative writes a live token to a file that outlives the run.
     *
     * <p>The response matters more than the request. A login sends a password and
     * gets back a JWT pair, so the token is in the body the suite is most likely
     * to log in full while debugging.
     */
    public static String redact(String s) {
        if (s == null) return null;
        // Matches a bare number as well as a quoted string: an OTP or MPIN is
        // usually sent unquoted, and a pattern that only handles "1234" walks
        // straight past 1234.
        return s.replaceAll(
                        "(?i)(\"(?:password|token|secret|secretKey|otp|mpin|pin|accessToken|refreshToken|authorization)\"\\s*:\\s*)(\"[^\"]*\"|\\d+)",
                        "$1\"***\"")
                .replaceAll("eyJ[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]*", "***jwt***");
    }

